import { verifyGoalBookPrintFonts } from '/home/enpasos/projects/skillpilot/app/scripts/buildGoalBookPublications.ts'
import { chromium } from '/home/enpasos/projects/skillpilot/app/node_modules/playwright/index.mjs'
import { writeFile } from 'node:fs/promises'
const output = process.argv[2]
await verifyGoalBookPrintFonts()
const browser = await chromium.launch({ executablePath: process.env.GOAL_BOOK_CHROMIUM_EXECUTABLE_PATH, headless: true })
try {
  const page = await browser.newPage()
  const rows = ['Arial', 'Courier New'].flatMap((family, familyIndex) => [
    {style: 'Regular', weight:400, cssStyle:'normal'},
    {style: 'Bold', weight:700, cssStyle:'normal'},
    {style: 'Italic', weight:400, cssStyle:'italic'},
    {style: 'Bold Italic', weight:700, cssStyle:'italic'},
  ].map((face,index) => ({...face, family, id:`face${familyIndex}-${index}`, expected:familyIndex===0?'Liberation Sans':'Liberation Mono'})))
  await page.setContent(`<html><body>${rows.map(r=>`<p id="${r.id}" style="font-family:'${r.family}';font-weight:${r.weight};font-style:${r.cssStyle}">Abc 123</p>`).join('')}</body></html>`)
  await page.evaluate(() => document.fonts.ready)
  const cdp = await page.context().newCDPSession(page)
  await cdp.send('DOM.enable'); await cdp.send('CSS.enable')
  const {root} = await cdp.send('DOM.getDocument')
  const actualFaces = []
  for(const row of rows) {
    const {nodeId} = await cdp.send('DOM.querySelector', {nodeId:root.nodeId, selector:`#${row.id}`})
    const {fonts} = await cdp.send('CSS.getPlatformFontsForNode', {nodeId})
    if(fonts.length !== 1 || fonts[0].familyName !== row.expected || fonts[0].glyphCount < 1) throw new Error(JSON.stringify({row,fonts}))
    actualFaces.push({...row, actualPlatformFonts:fonts})
  }
  const result = {role:'LOCAL_ENVIRONMENT_ONLY_NO_BOOK_OR_PDF_BUILD', nativeUnchangedVerifyGoalBookPrintFonts:'PASS', chromiumVersion:browser.version(), executablePath:process.env.GOAL_BOOK_CHROMIUM_EXECUTABLE_PATH, FONTCONFIG_FILE:process.env.FONTCONFIG_FILE, actualBrowserEightFaceBindings:actualFaces, rendererBuildOrPDFFilesCreated:0, activeCurriculumOrRepoCodeWrites:0}
  await writeFile(output, JSON.stringify(result,null,2)+'\n')
  console.log(JSON.stringify({nativeFontPreflight:'PASS', chromiumVersion:result.chromiumVersion, actualBrowserFaces:actualFaces.length, PDFOrBookBuilds:0}))
} finally { await browser.close() }
